using System.Linq;using UnityEngine;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class InspectHud08Dock{public static object Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();object Tree(RectTransform root)=>root.GetComponentsInChildren<RectTransform>(true).Select(r=>new{name=r.name,parent=r.parent.name,active=r.gameObject.activeSelf,anchor=r.anchorMin.ToString()+"/"+r.anchorMax,pivot=r.pivot.ToString(),pos=r.anchoredPosition.ToString(),size=r.sizeDelta.ToString(),components=r.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray();return new{scene=EditorSceneManager.GetActiveScene().path,playing=Application.isPlaying,dirty=EditorSceneManager.GetActiveScene().isDirty,bar=Tree(h.Layout.ConstructionBar),sections=h.Sections.Select(s=>s.Id+"="+s.Body.name).ToArray(),objective=h.Layout.FirstLoopObjective.name,notification=Tree(h.Layout.Notifications)};}}
